  // (This is a conceptual implementation; actual code depends on project specifics)
  #include <math.h>
  #include "model.h"

  // Assume helper functions for forward pass, loss, and input gradient exist or are created
  void compute_input_gradient(const Model* model, const float* input, const int* label, float* gradient);

  void generate_adversarial_example(const Model* model, const float* input_image, const int* true_label, float epsilon, float* adversarial_image) {
      int input_size = model->layers[0].input_size;
      float* gradient = (float*)malloc(input_size * sizeof(float));
      if (!gradient) return; // Handle allocation failure

      // 1. Compute gradient of loss w.r.t. input
      compute_input_gradient(model, input_image, true_label, gradient);

      // 2. Apply FGSM formula and clip
      for (int i = 0; i < input_size; ++i) {
          float sign = (gradient[i] > 0) ? 1.0f : -1.0f;
          adversarial_image[i] = input_image[i] + epsilon * sign;
          // Clip the values to a valid range, e.g., [0, 1]
          if (adversarial_image[i] < 0.0f) adversarial_image[i] = 0.0f;
          if (adversarial_image[i] > 1.0f) adversarial_image[i] = 1.0f;
      }

      free(gradient);
  }
  ```

